<style>
.po-shell{font-family:Inter,system-ui,sans-serif;color:#20312e}.po-bar{position:sticky;top:0;z-index:40;background:#fff;border-bottom:1px solid #e1e7e3;padding:14px 24px;display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap}.po-btn{border:0;border-radius:10px;padding:11px 18px;font-weight:650;background:#0f766e;color:#fff;cursor:pointer}.po-btn:disabled{opacity:.5}.po-secondary{background:#edf4f1;color:#23554b}.po-danger{background:#fff1f2;color:#9f1239}.po-panel{max-width:680px;margin:24px auto;padding:28px;border:1px solid #e1e7e3;background:#fff;border-radius:18px}.po-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.po-field{display:block;margin:12px 0}.po-field span{display:block;font-size:14px;font-weight:600;margin-bottom:6px}.po-input{width:100%;padding:11px;border:1px solid #cbd5d1;border-radius:9px;background:#fff;color:#20312e}.po-muted{font-size:14px;color:#67766e}.po-error{padding:14px;border-radius:10px;background:#fff1f2;color:#9f1239;margin:12px 0}.po-overlay{position:fixed;inset:0;background:#0b211ba8;z-index:80;display:flex;justify-content:flex-end}.po-drawer{background:#fff;width:520px;max-width:100%;height:100%;overflow:auto;padding:24px;box-shadow:-10px 0 40px #0002}.po-modal{position:fixed;inset:0;background:#0b211ba8;z-index:90;display:flex;align-items:center;justify-content:center;padding:16px}.po-dialog{background:#fff;border-radius:18px;padding:26px;width:600px;max-width:100%;max-height:90vh;overflow:auto}.po-row{display:flex;align-items:center;justify-content:space-between;gap:12px}.po-line{padding:16px 0;border-bottom:1px solid #e1e7e3}.po-check{display:block;margin:8px 0}.po-total{font-size:22px;font-weight:700}.po-notice{padding:18px;background:#e8f5ed;border-radius:12px;color:#23554b}.po-title{font:600 28px Georgia,serif;margin:0 0 12px}.po-history{max-width:1000px;margin:32px auto;padding:0 20px}@media(max-width:560px){.po-grid{grid-template-columns:1fr}.po-panel{margin:16px;padding:20px}.po-bar{padding:12px 16px}}
</style>
